def longest_without_repeat(rota):
    last = {}
    left = 0
    best = 0
    for day, name in enumerate(rota):
        if name in last and last[name] >= left:
            left = last[name] + 1
        last[name] = day
        best = max(best, day - left + 1)
    return best
